import z3

# Parameters
num_golfers = 21
num_weeks = 5
group_size = 3
num_groups = num_golfers // group_size  # 7

# Variables: x[w][g] = group assignment (0..6)
x = [[z3.Int(f"x_{w}_{g}") for g in range(num_golfers)] for w in range(num_weeks)]

solver = z3.Solver()

# Domain constraints
for w in range(num_weeks):
    for g in range(num_golfers):
        solver.add(x[w][g] >= 0)
        solver.add(x[w][g] < num_groups)

# Each group has exactly 3 golfers each week
for w in range(num_weeks):
    for k in range(num_groups):
        # Count how many golfers are in group k
        solver.add(z3.PbEq([(x[w][g] == k, 1) for g in range(num_golfers)], group_size))

# No pair meets more than once
# For each pair (g1, g2), they can be in the same group at most once across all weeks
for g1 in range(num_golfers):
    for g2 in range(g1+1, num_golfers):
        # Count weeks where they are in same group
        same_group = [z3.If(x[w][g1] == x[w][g2], 1, 0) for w in range(num_weeks)]
        solver.add(z3.Sum(same_group) <= 1)

print("Constraints added. Solving...")
result = solver.check()
print("Result:", result)

if result == z3.sat:
    model = solver.model()
    # Extract solution
    solution = []
    for w in range(num_weeks):
        for g in range(num_golfers):
            solution.append(model.evaluate(x[w][g]).as_long())
    print("Solution:", solution)
    # Verify
    print("Verifying...")
    # Check group sizes
    for w in range(num_weeks):
        counts = [0]*num_groups
        for g in range(num_golfers):
            counts[solution[w*21+g]] += 1
        print(f"Week {w}: group counts = {counts}")
    # Check pair constraints
    pair_weeks = {}
    for g1 in range(num_golfers):
        for g2 in range(g1+1, num_golfers):
            for w in range(num_weeks):
                if solution[w*21+g1] == solution[w*21+g2]:
                    pair = (g1,g2)
                    if pair in pair_weeks:
                        print(f"ERROR: pair {pair} meets in weeks {pair_weeks[pair]} and {w}")
                    pair_weeks[pair] = w
    print("Verification done.")
else:
    print("UNSAT")
